def transform(grid):
    h,w=len(grid),len(grid[0])
    candidates=[]
    for c in range(w):
        if c==w//2 and w%2==1 and all(row[c]==grid[0][c] for row in grid) and c==w-c-1:
            candidates.append(('v',c))
    for r in range(h):
        if r==h//2 and h%2==1 and all(x==grid[r][0] for x in grid[r]) and r==h-r-1:
            candidates.append(('h',r))
    if len(candidates)!=1: raise ValueError(candidates)
    axis,k=candidates[0]
    if axis=='v':
        a=[row[:k] for row in grid]; b=[row[k+1:] for row in grid]
    else:
        a=grid[:k]; b=grid[k+1:]
    shared=set(x for row in a for x in row)&set(x for row in b for x in row)
    mismatch=next(iter(shared))
    return [[3 if a[r][c]==b[r][c] else mismatch for c in range(len(a[0]))] for r in range(len(a))]

